INSERT INTO public.knowledge_chunks VALUES (71, 3, 0, '华南农业大学（South China Agricultural University，简称华农/SCAU）是一所以农业科学、生命科学为优势的全国重点大学。学校位于广东省广州市，始创于1909年，是广东省和农业农村部共建高校。学校有24个学院（部），在校生约5万人，专任教师约3000人。学校拥有农业科学、植物学与动物学、化学、微生物学、材料科学等11个ESI世界排名前1%学科。', '{"chunk": 0, "source_title": "华农介绍"}', '[-0.054446172,0.102916546,-0.018665152,0.04961389,-0.07030786,0.045445584,-0.034416176,-0.025323372,-0.068943016,-0.055774126,-0.012966009,0.04883925,-0.10653153,-0.008691653,-0.016378116,0.019163134,-0.025452478,0.02222481,-0.03939601,0.003617295,0.03380753,0.06687731,-0.03828938,0.06551246,-0.0406133,-0.014395406,0.032608684,-0.027555075,0.025729137,-0.0067181634,-0.025434034,0.11486814,0.1347137,0.021376394,0.010844969,0.095096365,-0.007497415,-0.00014884744,0.02541559,0.03616834,0.012615576,0.018582154,-0.027130866,-0.007940067,0.026005793,-0.05020409,0.0030293982,0.07388596,0.046736654,0.022243252,-0.044486504,-0.04835971,-0.0327009,0.03177871,0.032627128,-0.019808669,-0.043269213,-0.017254198,-0.02362654,-0.013150447,0.047363743,-0.009664564,0.012182146,-0.008954477,0.06562313,0.017097427,-0.0050720517,-0.074697495,0.01427552,-0.011693385,0.033678424,-0.035135485,-0.01118618,0.040908404,0.041055955,0.0704923,0.029639227,0.011278399,0.02087841,-0.015022496,0.021523943,-0.011794826,0.04522426,0.07344331,-0.0066028894,-0.02410608,0.019034028,0.0034005803,-0.0010443816,-0.0042397743,0.018305495,-0.015059383,-0.057507847,-0.00320692,0.037145864,0.015557366,-0.055220813,-0.021800602,-0.010798859,0.05212225,0.0013683012,-0.04378564,0.0054224846,0.020952186,0.080119975,-0.009922778,0.04470783,-0.018554488,-0.011389062,-0.05212225,-0.011057073,-0.013021341,-0.014423071,0.030358536,0.034453064,0.01735564,-0.031206952,-0.039137796,-0.0049014464,0.02628245,0.02323922,-0.0037302636,0.03461906,-0.057581622,0.01451529,0.024032304,-0.013058228,0.012624798,0.016092237,0.018010395,0.04256835,-0.004131417,0.022870343,0.011296843,-0.002063403,0.031465165,-0.045777574,0.01726342,0.022095703,0.02028